"use strict";(globalThis.webpackChunklinux_cleanup_docs||=[]).push([[4864],{73985(e){e.exports=JSON.parse('{"ecosystem":{"band":{"title":"More from Zaions","lead":"Other tools from the team behind linux-cleanup. Each one is described from the side of someone who already reads paths before deleting them.","seeAll":"See all products from Zaions","visit":"Visit {product}","details":"Details","pause":"Pause the product carousel","play":"Play the product carousel","prev":"Previous product","next":"Next product","slide":"{index} of {count}","eyebrow":"Zaions"},"page":{"eyebrow":"ZAIONS PRODUCTS","h1":"The rest of the shelf.","intro_one":"{count} product from the same team, each listed with one line on what it does. linux-cleanup is not in the list; you are already here.","intro_other":"{count} products from the same team, each listed with one line on what it does. linux-cleanup is not in the list; you are already here."},"view":{"label":"View","grid":"Cards","list":"List","table":"Table"},"table":{"product":"Product","what":"What it does","link":"Link"},"detail":{"back":"All products from Zaions","facts":"From the product\'s own pages, checked {date}."},"kind":{"web-app":"Web app","mobile-app":"Android app","package":"npm package","desktop-app-cli":"Desktop app + CLI","browser-extension":"Browser extension","wordpress-plugin-saas":"WordPress plugin","saas-package":"Service + npm package"},"footer":{"credit":"linux-cleanup \u2014 developed with love by the Zaions team","copyright":"\xa9 {year} linux-cleanup","aboutDeveloper":"About the developer","ecosystem":"More from Zaions"},"products":{"achat":{"card":"Messages with people you chose, no phone number handed over.","title":"AchatAI, for talking without giving out a number","intro":"AchatAI is a messaging app on the web and Android for people you chose. Someone can reach you by username, invite link or QR code.","sections":[{"heading":"Who is AchatAI for?","body":"People who want to message the ones they picked, on the web or on Android."},{"heading":"Does someone need your phone number?","body":"No. A username, an invite link or a QR code is enough to find you."},{"heading":"Can you talk without an account?","body":"Yes, in an anonymous room. It opens without signing up."},{"heading":"What links it to linux-cleanup?","body":"Both hand over less than you expect. linux-cleanup keeps file paths on your machine; AchatAI keeps your number out of the conversation."}],"facts":["achat-1","achat-2","achat-3"]},"callvault":{"card":"Call recordings that stay on the phone until you say otherwise.","title":"CallVault and where your recordings live","intro":"CallVault records calls on Android through the audio source the phone makes available. The recordings stay on that phone unless you turn on private cloud backup.","sections":[{"heading":"How does CallVault record a call?","body":"It uses the audio source the Android phone makes available for the call."},{"heading":"Where are the recordings kept?","body":"On the phone. They leave it only when you enable private cloud backup."},{"heading":"What can you do with a recording?","body":"Play it, search the library, add notes and export it."},{"heading":"What links it to linux-cleanup?","body":"The same rule about data: it stays on the device you own until you choose to move it."}],"facts":["callvault-1","callvault-2","callvault-3"]},"capacitor-auth-manager":{"card":"Google sign-in for Capacitor apps, with no Firebase dependency.","title":"Capacitor Auth Manager without the Firebase dependency","intro":"Capacitor Auth Manager is an npm package with one Google sign-in call for web, Android and iOS. It does not pull in Firebase.","sections":[{"heading":"What does the package do?","body":"It gives a Capacitor app one Google sign-in call that works on web, Android and iOS."},{"heading":"Does it need Firebase?","body":"No. Firebase is not a dependency."},{"heading":"Which providers are on in version 3.x?","body":"Google is the only enabled provider in 3.x."},{"heading":"What links it to linux-cleanup?","body":"Both ship from npm. If you count what a dependency drags into node_modules, this one leaves Firebase out."}],"facts":["capacitor-auth-manager-1","capacitor-auth-manager-2","capacitor-auth-manager-3"]},"clearhire":{"card":"Check a resume against ATS rules before you send it.","title":"ClearHire before the application goes out","intro":"ClearHire is a resume builder with structured profiles and more than 50 career tools. One of them checks a resume against applicant tracking systems.","sections":[{"heading":"What is ClearHire?","body":"A resume builder that keeps your profile in structured fields, built to be read by applicant tracking systems."},{"heading":"What can you check before sending?","body":"The career tools run from bullet writing to ATS checks, more than 50 of them."},{"heading":"How does a profile earn more trust?","body":"Verified-employment workflows add proof to the work history you list."},{"heading":"What links it to linux-cleanup?","body":"The habit of looking before acting. A dry run shows the cleanup first; an ATS check shows the resume first."}],"facts":["clearhire-2","clearhire-3","clearhire-4"]},"eatthis":{"card":"See what one serving gives before you pick it.","title":"Eat This and the numbers behind one serving","intro":"Eat This lets you look for food by nutrient, by how you feel or by time of day. It shows how much of a nutrient one serving gives.","sections":[{"heading":"How do you search in Eat This?","body":"By nutrient, by feeling or by the time of day."},{"heading":"What does it show for a food?","body":"How much of a nutrient one serving provides."},{"heading":"Does it point to a cheaper option?","body":"Yes. It identifies a cheap pick, and it says when a question belongs with a doctor."},{"heading":"What links it to linux-cleanup?","body":"Both show an amount before a decision: a cache size before cleanup, a nutrient amount before a meal."}],"facts":["eatthis-1","eatthis-2","eatthis-3"]},"empora":{"card":"WooCommerce modules you switch on one by one.","title":"Empora with only the modules a store uses","intro":"Empora puts WooCommerce store modules in one WordPress plugin. A merchant decides which modules are switched on.","sections":[{"heading":"What is Empora?","body":"A WordPress plugin that carries several WooCommerce store modules."},{"heading":"Do all modules run at once?","body":"No. The merchant chooses which ones to switch on."},{"heading":"What does the web dashboard handle?","body":"Licences and optional store connections."},{"heading":"What links it to linux-cleanup?","body":"Selection by name. linux-cleanup runs the sections you pick; Empora runs the modules you pick."}],"facts":["empora-1","empora-2","empora-3"]},"habitforge":{"card":"A habit record that shows the exact day it stopped.","title":"HabitForge and the gap you can see","intro":"HabitForge draws consistency as a rope. It thickens with each check-in and frays where you stopped.","sections":[{"heading":"How does HabitForge show a habit?","body":"As a rope that grows thicker with every check-in."},{"heading":"What happens when you miss days?","body":"The rope frays at the point where you stopped, so the gap is visible."},{"heading":"Can other people join in?","body":"Friends, challenges and a leaderboard are there, and you can leave the leaderboard."},{"heading":"What links it to linux-cleanup?","body":"A receipt you can read later. linux-cleanup lists what a run removed; HabitForge shows what happened on each day. It runs on the web and Android from one account."}],"facts":["habitforge-1","habitforge-2","habitforge-3","habitforge-4"]},"labflow":{"card":"Lab results that move from draft to released, step by step.","title":"LabFlow and the path a result takes","intro":"LabFlow runs a diagnostic lab from patient and order to sample and result. A result passes a validation workflow before it is released.","sections":[{"heading":"What does LabFlow cover?","body":"Patients, orders, samples and results in one system."},{"heading":"How is a result released?","body":"Through a validation workflow that moves it from draft to released."},{"heading":"What else does the lab run in it?","body":"Billing, inventory and quality control."},{"heading":"What links it to linux-cleanup?","body":"A defined step before the final one. A dry run comes before a real run; validation comes before release."}],"facts":["labflow-1","labflow-2","labflow-3","labflow-4"]},"lifewell":{"card":"Vitals, water, meds and sleep logged in one record.","title":"LifeWell, one record for several health logs","intro":"LifeWell keeps vitals, water, medication, sleep and nutrition in one app. It runs on the web and Android and syncs between them.","sections":[{"heading":"What can you log in LifeWell?","body":"Vitals, water, medication, sleep and nutrition."},{"heading":"Does it cover cycles and babies?","body":"Periods, fertility and baby milestones are included."},{"heading":"Which devices does it run on?","body":"The web and Android, synced across devices."},{"heading":"What links it to linux-cleanup?","body":"One place instead of many. linux-cleanup gathers scattered caches into one survey; LifeWell gathers scattered health notes into one record."}],"facts":["lifewell-2","lifewell-3","lifewell-4"]},"macleanup":{"card":"The same section catalogue, on a Mac.","title":"macleanup for the Mac on the next desk","intro":"macleanup is the macOS counterpart of linux-cleanup. It uses the same section catalogue and runs a real dry run before anything is removed.","sections":[{"heading":"How close is it to linux-cleanup?","body":"It uses the same section catalogue, written for macOS."},{"heading":"What does it refuse?","body":"Personal folders, unconditionally."},{"heading":"Can you preview a run?","body":"Yes. A real dry run comes before anything is removed."},{"heading":"Who would use both?","body":"A team or household with Linux and Mac machines can follow the same steps on each."}],"facts":["macleanup-2","macleanup-3","macleanup-4"]},"native-update":{"card":"Ship a web-layer fix to Capacitor apps without the store wait.","title":"Native Update for the fix that cannot wait for review","intro":"Native Update delivers live over-the-air bundle updates to Capacitor apps. It also shows in-app prompts for store updates and reviews.","sections":[{"heading":"What problem does it solve?","body":"A Capacitor app update reaches users without waiting for the store."},{"heading":"How is the update delivered?","body":"As a live over-the-air bundle."},{"heading":"What about full store releases?","body":"In-app prompts ask the user to take the store update or leave a review."},{"heading":"Can you run the backend yourself?","body":"Yes. The backend is open source and self-hostable."}],"facts":["native-update-1","native-update-2","native-update-3","native-update-4"]},"netcage":{"card":"Take one Android app offline on the days you choose.","title":"NetCage for one app, not the whole phone","intro":"NetCage can refuse Wi-Fi and mobile data for a selected Android app while the rest of the phone stays online.","sections":[{"heading":"What does NetCage block?","body":"Wi-Fi, mobile data or both, for the app you select."},{"heading":"Does the rest of the phone go offline?","body":"No. Only the selected app loses its connection."},{"heading":"Can a rule follow a schedule?","body":"Yes. Profiles group apps and apply rules on chosen days and times."},{"heading":"What links it to linux-cleanup?","body":"Narrow scope by design. linux-cleanup removes only the sections you select; NetCage blocks only the apps you select."}],"facts":["netcage-1","netcage-2","netcage-3"]},"pregnancypal":{"card":"A pregnancy record that exports as a PDF for your doctor.","title":"PregnancyPal and the export you take to an appointment","intro":"PregnancyPal tracks a pregnancy week by week, with nutrition and exercise. Vitals, symptoms, mood and appointments go into the same record.","sections":[{"heading":"What does PregnancyPal track?","body":"Each week of the pregnancy, with nutrition and exercise."},{"heading":"What can you log?","body":"Vitals, symptoms, mood and appointments."},{"heading":"Can a doctor read it?","body":"Yes. The record exports as a doctor-friendly PDF."},{"heading":"What links it to linux-cleanup?","body":"A record you can hand over. linux-cleanup writes a report after a run; PregnancyPal produces a PDF for an appointment."}],"facts":["pregnancypal-2","pregnancypal-3","pregnancypal-4"]},"rentparty":{"card":"A property-trading game night on one passed-around phone.","title":"RentParty when the game has to stop for dinner","intro":"RentParty is a property-trading game that can be paused. Players can pass one phone around, play against CPU characters or open an online room.","sections":[{"heading":"How many devices does it need?","body":"One phone passed around is enough; an online room is there too."},{"heading":"Can you play alone?","body":"Yes, against CPU characters."},{"heading":"What happens when you pause?","body":"The game keeps the bank and every deed in place until play resumes."},{"heading":"What links it to linux-cleanup?","body":"Nothing to do with disks, and that is the point: something to open once the cleanup is done."}],"facts":["rentparty-1","rentparty-2","rentparty-3"]},"smsapp":{"card":"Scheduled SMS batches sent from your own Android SIM.","title":"SMS App for messages from your own number","intro":"SMS App sends SMS at scale from your own Android device. Messages go one at a time, in batches or on a schedule.","sections":[{"heading":"Where are the messages sent from?","body":"Your own Android device and its SIM."},{"heading":"How can you send?","body":"Single messages, batches or scheduled sends."},{"heading":"Can several phones share the work?","body":"Devices can be registered into a volunteer pool."},{"heading":"What links it to linux-cleanup?","body":"Both run on hardware you already own. SMS App is Android-native and privacy-first."}],"facts":["smsapp-1","smsapp-2","smsapp-3","smsapp-4"]},"strata-storage":{"card":"Keychain and Keystore behind one storage interface.","title":"Strata Storage for the secret that should not sit in localStorage","intro":"Strata Storage is one storage API over localStorage, IndexedDB, cookies and native storage. On iOS and Android it reaches Keychain and Keystore.","sections":[{"heading":"What does Strata Storage replace?","body":"Separate code for localStorage, IndexedDB, cookies and native storage."},{"heading":"Where does a secret go on a phone?","body":"Into Keychain on iOS and Keystore on Android, through the same interface."},{"heading":"Does it add dependencies?","body":"No. It has zero dependencies and runs on web, iOS and Android."},{"heading":"What links it to linux-cleanup?","body":"The linux-cleanup desktop app and website keep their settings through Strata Storage."}],"facts":["strata-storage-1","strata-storage-2","strata-storage-3","strata-storage-4"]},"tilawah":{"card":"Live Quran recitation sessions booked in your own timezone.","title":"Tilawah and a teacher at a time that suits you","intro":"Tilawah offers recorded Tajweed and Tafseer lessons and live one-on-one recitation sessions. Sessions are booked in the learner\'s timezone.","sections":[{"heading":"What does Tilawah teach?","body":"Tajweed and Tafseer, through recorded lessons."},{"heading":"Can you go at your own pace?","body":"Yes. Progress through the self-paced lessons is tracked."},{"heading":"How do live sessions work?","body":"One-on-one recitation sessions, booked in your own timezone."},{"heading":"What links it to linux-cleanup?","body":"Only the maker. Both come from the Zaions team, and Tilawah stands on its own."}],"facts":["tilawah-1","tilawah-2","tilawah-3"]},"trizlink":{"card":"Branded short links with the clicks counted.","title":"Trizlink and what happens after a link is shared","intro":"Trizlink makes branded short links with custom slugs and counts the clicks. It also builds link-in-bio pages on custom domains.","sections":[{"heading":"What can you shorten?","body":"Any link, under your own brand and a custom slug."},{"heading":"What does it count?","body":"Clicks, through built-in click analytics."},{"heading":"Is there a page for a profile bio?","body":"Yes. Link-in-bio pages, with custom domains."},{"heading":"What else is included?","body":"More than 50 built-in utilities."}],"facts":["trizlink-1","trizlink-2","trizlink-3","trizlink-4"]},"video-controls-plus":{"card":"Frame-step and A\u2013B loop for studying any HTML5 video.","title":"Video Controls Plus for watching one part again","intro":"Video Controls Plus is a browser extension that controls any HTML5 video. It loops an A\u2013B section, steps frame by frame and sets speed from 0.1\xd7 to 16\xd7.","sections":[{"heading":"How do you study a short part of a video?","body":"Set an A\u2013B loop and step through it frame by frame."},{"heading":"How slow or fast can it play?","body":"From 0.1\xd7 to 16\xd7."},{"heading":"Can you keep notes?","body":"Yes. Screenshots and timestamped notes, with more than 40 shortcuts."},{"heading":"What about the sound and picture?","body":"Audio boost up to 400%, filters and colour correction."}],"facts":["video-controls-plus-1","video-controls-plus-2","video-controls-plus-4","video-controls-plus-3"]},"waylock":{"card":"Keep the chosen route on screen after a wrong turn.","title":"Waylock and the route you already decided on","intro":"Waylock is an Android planning layer over Google Maps for drivers and couriers. A driver holds chosen stops in place and orders the rest around them.","sections":[{"heading":"Who is Waylock for?","body":"Drivers and couriers who plan stops on Android over Google Maps."},{"heading":"Can some stops stay fixed?","body":"Yes. Chosen stops stay in place and the rest are ordered around them."},{"heading":"What happens after a wrong turn?","body":"The chosen route stays visible beside the option to return to it or take a new route."},{"heading":"What links it to linux-cleanup?","body":"A plan you set stays the plan. A real run follows the sections you confirmed, nothing added on the way."}],"facts":["waylock-1","waylock-2","waylock-3"]},"windowsweep":{"card":"Windows cleanup with personal files chosen row by row.","title":"windowsweep for the Windows machine beside your Linux one","intro":"windowsweep is a Windows cleanup tool that runs a dry run first. Personal files are chosen row by row, never swept as a group.","sections":[{"heading":"How does it handle personal files?","body":"You choose them row by row."},{"heading":"Does it show paths first?","body":"Yes. It names every path before it touches one, across 30 sections, with a real dry run."},{"heading":"Does it call the network?","body":"No network calls, as the product states."},{"heading":"How do you run it?","body":"With npx windowsweep, or as a Windows desktop app."}],"facts":["windowsweep-1","windowsweep-2","windowsweep-3","windowsweep-4"]},"ztools":{"card":"Developer utilities that run in the browser and upload nothing.","title":"ZTools when the input should not leave your machine","intro":"ZTools is a toolbox of developer and creator utilities. Each one runs in the browser, so your input is not uploaded.","sections":[{"heading":"What tools does it carry?","body":"Formatters, converters, encoders and generators."},{"heading":"Where does your input go?","body":"Nowhere. The tools run in the browser and nothing is uploaded."},{"heading":"Does it work offline?","body":"Yes. It is searchable, dark-mode-first and works offline."},{"heading":"What links it to linux-cleanup?","body":"Your paths stay on your machine during a cleanup; your input stays in your browser in ZTools."}],"facts":["ztools-1","ztools-2","ztools-3","ztools-4"]}}},"about":{"title":"About the developer \xb7 linux-cleanup","description":"Ahsan Mahmood built linux-cleanup so a Linux machine can drop caches and leftovers without touching personal files. Why he built it and how it got here, with dates.","eyebrow":"ABOUT THE DEVELOPER","h1":"Built by Ahsan Mahmood.","lead":"Ahsan Mahmood (aoneahsan) built linux-cleanup after his own disks kept filling with caches nobody needed. He runs Zaions, the team behind it.","portfolio":"Visit Ahsan\'s portfolio","zaions":"Zaions","sections":[{"id":"why","h2":"Why it exists","p":["A developer machine fills up with things that can be rebuilt: package caches, build output, logs, leftovers from software that is already gone. Ahsan wanted one tool that clears those and leaves personal files alone.","He wanted it free for anyone who needs it. The command line is free and MIT-licensed; the desktop app adds a window, a schedule and a receipt for people who want them.","It is for anyone running Linux, not only developers. It began as the Linux side of the same idea he applied to the Mac in macleanup."]},{"id":"journey","h2":"How it got here","timeline":[["2026-05-09","linux-cleanup 1.0.0: a Bash script that runs with npx, nothing to install."],["2026-09-18","1.6.0, the last release of the first line."],["2026-11-10","Rebuilt as 2.0.0 with a real dry run and a release check."],["2026-11-13","This website went live."],["2026-11-21","The documentation moved to 2.x, CLI 2.1.0 shipped, and desktop app 1.0.0 was released for x86_64 Linux."],["2026-11-22","Plans opened for the desktop app; desktop 1.0.4 and CLI 2.1.1 are the current releases."]]},{"id":"built","h2":"How it is built","p":["The engine is the Bash command line, published on npm. The desktop app is a Tauri window around that same engine, so both remove exactly the same paths.","File paths stay on your machine. With an account, a run summary keeps sizes, section numbers and the OS version, never the paths. The website and the app count usage and report errors so the next release can be better; the privacy policy names each service.","Every removal is permanent. A dry run lists what a real run would remove, and a receipt lists what it did."]},{"id":"more","h2":"More from Ahsan and Zaions","links":[["/ecosystem","Products from Zaions"],["https://aoneahsan.com/projects","Ahsan\'s projects"],["https://zaions.com","zaions.com"],["https://github.com/aoneahsan","GitHub"],["https://www.linkedin.com/in/aoneahsan","LinkedIn"]]},{"id":"contact","h2":"Questions and bug reports","p":["Open an issue on the linux-cleanup repository. Include the version from linux-cleanup --version and what you ran."],"link":["https://github.com/aoneahsan/linux-cleanup/issues","Open an issue"]}]}}')}}]);